def compile_mjcf(facts,out):
 O=['baseplate','front_left_column','rear_left_column','front_right_column','rear_right_column','upper_bridge','input_thrust_button','compound_thrust_button','output_thrust_button','input_lower_bearing','compound_lower_bearing','output_lower_bearing','input_upper_bearing','compound_upper_bearing','output_upper_bearing','input_shaft','input_pinion','hand_crank','crank_handle','compound_shaft','compound_wheel','compound_pinion','output_shaft','output_gear','output_coupling']
 P={'baseplate':'','front_left_column':'baseplate','rear_left_column':'baseplate','front_right_column':'baseplate','rear_right_column':'baseplate','upper_bridge':'front_left_column','input_thrust_button':'baseplate','compound_thrust_button':'baseplate','output_thrust_button':'baseplate','input_lower_bearing':'baseplate','compound_lower_bearing':'baseplate','output_lower_bearing':'baseplate','input_upper_bearing':'upper_bridge','compound_upper_bearing':'upper_bridge','output_upper_bearing':'upper_bridge','input_shaft':'baseplate','input_pinion':'input_shaft','hand_crank':'input_shaft','crank_handle':'hand_crank','compound_shaft':'baseplate','compound_wheel':'compound_shaft','compound_pinion':'compound_shaft','output_shaft':'baseplate','output_gear':'output_shaft','output_coupling':'output_shaft'}
 J={'input_shaft':'input_shaft_rotation','input_pinion':'input_shaft_rotation','hand_crank':'input_shaft_rotation','crank_handle':'input_shaft_rotation','compound_shaft':'compound_shaft_rotation','compound_wheel':'compound_shaft_rotation','compound_pinion':'compound_shaft_rotation','output_shaft':'output_shaft_rotation','output_gear':'output_shaft_rotation','output_coupling':'output_shaft_rotation'}
 C={}
 for n in O:C[n]=J[n] if n in J else None
 N={'input_shaft':['upper_bridge','input_thrust_button','input_lower_bearing','input_upper_bearing','input_pinion','compound_wheel','hand_crank','baseplate','crank_handle','compound_pinion','compound_lower_bearing','compound_upper_bearing','compound_shaft','compound_thrust_button','front_left_column','rear_left_column','output_gear'],'compound_shaft':['upper_bridge','compound_thrust_button','compound_lower_bearing','compound_upper_bearing','compound_wheel','compound_pinion','output_gear','baseplate','hand_crank','input_pinion','input_lower_bearing','input_upper_bearing','input_shaft','output_coupling','input_thrust_button','crank_handle','output_lower_bearing','output_upper_bearing','output_shaft','output_thrust_button'],'output_shaft':['upper_bridge','output_thrust_button','output_lower_bearing','output_upper_bearing','output_gear','output_coupling','baseplate','compound_wheel','compound_pinion','compound_lower_bearing','compound_upper_bearing','compound_shaft','compound_thrust_button'],'input_pinion':['input_shaft','compound_wheel','input_lower_bearing','input_thrust_button','baseplate'],'compound_wheel':['input_shaft','compound_shaft','input_pinion','input_lower_bearing','compound_lower_bearing','output_lower_bearing','compound_pinion','output_gear','output_shaft','compound_thrust_button','input_thrust_button','baseplate','output_thrust_button','front_left_column','rear_left_column','upper_bridge','input_upper_bearing','compound_upper_bearing','output_upper_bearing'],'compound_pinion':['compound_shaft','output_gear','upper_bridge','compound_upper_bearing','compound_wheel'],'output_gear':['front_right_column','rear_right_column','compound_shaft','output_shaft','compound_pinion','upper_bridge','compound_upper_bearing','output_upper_bearing','compound_wheel','compound_lower_bearing','output_lower_bearing','output_coupling','output_thrust_button','compound_thrust_button','baseplate','input_pinion','input_upper_bearing','input_shaft','input_lower_bearing','hand_crank','input_thrust_button','crank_handle','front_left_column','rear_left_column'],'hand_crank':['input_shaft','crank_handle','upper_bridge','input_upper_bearing','compound_shaft','compound_upper_bearing','front_left_column'],'crank_handle':['hand_crank'],'output_coupling':['output_shaft','upper_bridge','output_upper_bearing']}
 R={tuple(sorted(['input_pinion','compound_wheel'])):(['relation/stage_1_mesh'],['fit/input_pinion/teeth/compound_wheel/teeth','pair/compound_wheel/input_pinion'],'ideal external gear equality replaces tooth contact'),tuple(sorted(['compound_pinion','output_gear'])):(['relation/stage_2_mesh'],['fit/compound_pinion/teeth/output_gear/teeth','pair/compound_pinion/output_gear'],'ideal external gear equality replaces tooth contact')}
 F=[['input_pinion','input_shaft','input_pinion_press_fit','fit/input_pinion/bore/input_shaft/pinion_seat','pair/input_pinion/input_shaft'],['compound_wheel','compound_shaft','compound_wheel_press_fit','fit/compound_wheel/bore/compound_shaft/wheel_seat','pair/compound_shaft/compound_wheel'],['compound_pinion','compound_shaft','compound_pinion_press_fit','fit/compound_pinion/bore/compound_shaft/pinion_seat','pair/compound_pinion/compound_shaft'],['output_gear','output_shaft','output_gear_press_fit','fit/output_gear/bore/output_shaft/gear_seat','pair/output_gear/output_shaft'],['hand_crank','input_shaft','crank_press_fit','fit/hand_crank/shaft_bore/input_shaft/crank_seat','pair/hand_crank/input_shaft'],['output_coupling','output_shaft','output_coupling_press_fit','fit/output_coupling/shaft_bore/output_shaft/coupling_seat','pair/output_coupling/output_shaft']]
 for x in F:R[tuple(sorted([x[0],x[1]]))]=(['relation/'+x[2]],[x[3],x[4]],'measured interference is a rigid press fit')
 F=[['input_lower_bearing','input_shaft','input_lower_journal','fit/input_lower_bearing/journal/input_shaft/lower_journal','pair/input_lower_bearing/input_shaft'],['input_upper_bearing','input_shaft','input_upper_journal','fit/input_upper_bearing/journal/input_shaft/upper_journal','pair/input_shaft/input_upper_bearing'],['compound_lower_bearing','compound_shaft','compound_lower_journal','fit/compound_lower_bearing/journal/compound_shaft/lower_journal','pair/compound_lower_bearing/compound_shaft'],['compound_upper_bearing','compound_shaft','compound_upper_journal','fit/compound_upper_bearing/journal/compound_shaft/upper_journal','pair/compound_shaft/compound_upper_bearing'],['output_lower_bearing','output_shaft','output_lower_journal','fit/output_lower_bearing/journal/output_shaft/lower_journal','pair/output_lower_bearing/output_shaft'],['output_upper_bearing','output_shaft','output_upper_journal','fit/output_upper_bearing/journal/output_shaft/upper_journal','pair/output_shaft/output_upper_bearing']]
 for x in F:R[tuple(sorted([x[0],x[1]]))]=(['relation/'+x[2]],[x[3],x[4]],'measured clearance is a running journal represented by hinge')
 Q={}
 for a in N:
  for b in N[a]:Q[tuple(sorted([a,b]))]=1
 U=[tuple(sorted(['input_shaft','upper_bridge'])),tuple(sorted(['compound_shaft','upper_bridge'])),tuple(sorted(['output_shaft','upper_bridge']))]
 D=[]
 for p in sorted(Q):
  if p in R:s,i,r=R[p];ac='exclude'
  elif p in U:s=['link/'+p[0],'link/'+p[1]];i=['pair/'+p[0]+'/'+p[1]];r='solid overlap unavailable; retain uncertain contact';ac='keep'
  else:s=['link/'+p[0],'link/'+p[1]];i=['pair/'+p[0]+'/'+p[1]];r='separated surfaces or zero overlap extent indicate collision-proxy false contact';ac='exclude'
  D.append({'pair':[p[0],p[1]],'action':ac,'reason':r,'source_entity_ids':s,'fact_ids':i})
 T=[]
 for n in O:
  if P[n]:T.append([P[n],n])
 out.topology_plan({'coordinate_map':C,'tree_edges':T,'closure_edges':[['input_shaft_rotation','compound_shaft_rotation'],['compound_shaft_rotation','output_shaft_rotation']],'rigid_carried':{'input_shaft':['input_pinion','hand_crank','crank_handle'],'compound_shaft':['compound_wheel','compound_pinion'],'output_shaft':['output_gear','output_coupling']},'independent_coaxial':[],'transmissions':[{'name':'first_reduction','driving_joint':'input_shaft_rotation','driven_joint':'compound_shaft_rotation','ratio':-0.3333333333333333},{'name':'second_reduction','driving_joint':'compound_shaft_rotation','driven_joint':'output_shaft_rotation','ratio':-0.25}],'contact_decisions':D,'support_ground':'baseplate rests on plane','support_strategy':'remove gear equalities for support probe'})
 for n in O:
  out.body(n,P[n])
  if n in ['input_shaft','compound_shaft','output_shaft']:out.joint(n,J[n],kind='hinge',axis=(0,0,1),pos_mm=(0,0,0))
 out.joint_equality('stage_1_ratio','input_shaft_rotation','compound_shaft_rotation',-0.3333333333333333,reason='external pitch radii 4.8 and 14.4 mm',sources=['relation/stage_1_mesh','transmission/first_reduction'],fact_ids=['fit/input_pinion/teeth/compound_wheel/teeth'])
 out.joint_equality('stage_2_ratio','compound_shaft_rotation','output_shaft_rotation',-0.25,reason='external pitch radii 4.8 and 19.2 mm',sources=['relation/stage_2_mesh','transmission/second_reduction'],fact_ids=['fit/compound_pinion/teeth/output_gear/teeth'])
 for d in D:
  if d['action']=='exclude':out.exclude(d['pair'][0],d['pair'][1],d['reason'],d['source_entity_ids'],d['fact_ids'])
 out.support_patch(action='remove_constraint',name='stage_1_ratio',reason='isolate passive support under gravity')
 out.support_patch(action='remove_constraint',name='stage_2_ratio',reason='isolate passive support under gravity')
 M=['motion_joint/input_shaft_rotation','motion_joint/compound_shaft_rotation','motion_joint/output_shaft_rotation']
 for e in facts['entity_ids']:
  ac='represented_by';g=['baseplate']
  for n in O:
   if e=='link/'+n:ac='emitted';g=[n]
  for m in M:
   if e==m:ac='emitted';g=[m[13:]]
  out.decision(e,action=ac,generated_nodes=g,reason='entity compiled into the selected three-shaft topology',fact_ids=[e])
